export interface SparklineProps {
  /**
   * Numeric series. Order matters — index 0 is the oldest sample, index n
   * is the most recent. Caller is responsible for downsampling.
   */
  points: readonly number[];
  /** Width in px. */
  width?: number;
  /** Height in px. */
  height?: number;
  /**
   * Accessible label for the SVG. Required — the sparkline is meaningless
   * without context for screen-readers.
   */
  label: string;
  /**
   * When true, treats a final-point higher than the first as "good"
   * (accent stroke). When false (default) the sparkline is monochrome so
   * the page can reserve `var(--accent-ai)` for the headline tile only.
   */
  accent?: boolean;
  /** Extra class names — escape hatch for layout. */
  className?: string;
  /**
   * Index of the first PARTIAL (not yet final) point — e.g. today's spend
   * while the day is still running. The solid stroke stops at the last
   * complete point (`partialFromIndex - 1`); from there to the end a second,
   * dashed path is drawn, so the line reads "final up to here, still moving
   * after". Omitted (or ≥ `points.length`) draws one solid path, as before;
   * `0` draws the whole series dashed.
   */
  partialFromIndex?: number;
  /**
   * Stroke colour override (any CSS colour, e.g. `currentColor` or a series
   * colour). Takes precedence over `accent`. Omitted keeps the default:
   * `var(--accent-ai)` when `accent`, otherwise `currentColor`.
   */
  color?: string;
}

export interface MetricDeltaLabels {
  /** Title attribute when delta > 0 (receives the absolute % integer). */
  up: (pct: number) => string;
  /** Title attribute when delta < 0. */
  down: (pct: number) => string;
  /** Title attribute when the delta rounds to 0. */
  flat: string;
}

export interface MetricTile {
  /** Stable id — used for data-testid and React key. */
  id: string;
  /** 10px uppercase mono eyebrow label. */
  label: string;
  /** Accessible label fully describing the tile to screen readers. */
  ariaLabel: string;
  /** Formatted value (currency, count, percent, etc). */
  value: string;
  /**
   * Fractional delta vs previous period (e.g. 0.12 → 12%). Null suppresses
   * the delta indicator.
   */
  delta?: number | null;
  /** Whether a positive delta should render rose ("bad when up"). */
  deltaIsBadWhenUp?: boolean;
  /** Per-tile delta copy — wire through your i18n helper. */
  deltaLabels?: MetricDeltaLabels;
  /**
   * Optional sparkline series. Only the FIRST tile renders a sparkline
   * even when others supply points; the spec restricts the row to one
   * sparkline so the eye keeps scanning across.
   */
  sparkPoints?: readonly number[];
  /** Accessible label for the sparkline. */
  sparkLabel?: string;
  /** Optional click handler — turns the tile into a navigational target. */
  onClick?: () => void;
}

export interface MetricStripProps {
  /** Up to six tiles. Anything past index 5 is dropped. */
  tiles: readonly MetricTile[];
  /** When true, renders skeleton dots in place of values. */
  loading?: boolean;
  /** Extra class names. */
  className?: string;
}

interface MetricCellProps {
  tile: MetricTile;
